{
  "itinerary": {
    "destination": "Moscow, Russia",
    "duration_days": 3,
    "day_1": {
      "morning": "Visit the Red Square and St. Basil's Cathedral to see the iconic architecture of the capital.",
      "afternoon": "Walk along the Moscow River and explore the Gorky Park for a relaxing stroll.",
      "evening": "Dinner at a traditional Russian restaurant near the Kremlin walls."
    },
    "day_2": {
      "morning": "Tour the Kremlin complex, including the Armory and the Cathedral of the Annunciation.",
      "afternoon": "Explore the Pushkin Museum of Fine Arts to view masterpieces by Russian and European artists.",
      "evening": "Watch a performance at the Bolshoi Theatre or enjoy a view of the city lights from the Spasskaya Tower."
    },
    "day_3": {
      "morning": "Take a guided tour of the Moscow Metro to admire its unique artistic decorations and stations.",
      "afternoon": "Visit the Tretyakov Gallery to see the largest collection of Russian art in the world.",
      "evening": "Farewell dinner at a historic cafe in the Arbat Street district."
    }
  }
}
